-- ============================================================
-- PHARMAPROMPT OS -- APPLY PENDING MIGRATIONS TO LIVE LOVABLE CLOUD
-- ============================================================
-- Created: 2026-06-14
-- Author:  hughn78 (PharmaPrompt OS owner)
--
-- PURPOSE
-- Three Phase 5/6 migration files were committed and pushed to GitHub
-- but Lovable Cloud only auto-runs migrations authored through its
-- own agent. These three were never applied to the live DB:
--
--   * 20260614010000_seed_products_herbsofgold.sql
--       ALTER products (+4 columns) + INSERT 103 HOG rows
--   * 20260614020000_extend_medication_dictionary.sql
--       +21 psychiatric/other drugs
--   * 20260614030000_phase6_rationale_extension.sql
--       +8 cols on safety_rules, +8 cols on recommendations, backfill
--
-- This file consolidates them in dependency-safe order with
-- idempotency hardening. Safe to re-run; will report zero affected
-- rows and no errors when nothing needs to change.
--
-- DEPENDENCY ORDER
--   1. ALTER public.products           (adds columns INSERT needs)
--   2. CREATE INDEX ... products ...   (GIN / partial on reviewed)
--   3. DELETE + INSERT public.products (HOG seed, idempotent via brand)
--   4. INSERT public.medication_dictionary (ON CONFLICT DO NOTHING)
--   5. ALTER public.safety_rules       (adds Phase 6 cols)
--   6. CREATE INDEX ... safety_rules ...
--   7. UPDATE public.safety_rules      (severity_tier backfill)
--   8. UPDATE public.safety_rules      (evidence_level/rule_source/advice/safety_net backfill)
--   9. ALTER public.recommendations    (adds Phase 6 cols)
--  10. CREATE INDEX ... recommendations ...
--
-- IDEMPOTENCY NOTES
--   * All ALTER ... ADD COLUMN use IF NOT EXISTS -- safe to re-run.
--   * All CREATE INDEX use IF NOT EXISTS -- safe to re-run.
--   * medication_dictionary INSERT uses ON CONFLICT (generic_name) DO NOTHING.
--   * The products INSERT has no natural unique key (product_id is a
--     random UUID PK, notes holds the HOG-#### code but is not
--     constrained unique). To make this re-runnable we DELETE any
--     existing Herbs of Gold rows immediately before INSERT. This is
--     the simplest correct approach: brand='Herbs of Gold' is unique
--     to this seed (no other brand uses it in the live DB), and
--     recommendations.product_id is TEXT and not a FK to
--     products.product_id, so deleting products cannot orphan
--     recommendations. An alternative -- adding external_code TEXT
--     UNIQUE backfilled from notes and using ON CONFLICT -- was
--     considered and rejected as more schema surgery than this
--     one-shot remediation warrants.
--   * safety_rules backfill UPDATEs are guarded by WHERE clauses and
--     COALESCE so re-running only fills NULL cells. The 13 existing
--     rules still carry the legacy `severity` column on live
--     (Phase 6 was committed and pushed but never applied) -- the
--     first UPDATE will map them and the second pass is a no-op on
--     a re-run.
--   * The recommendations table has no legacy data needing
--     backfill; the 8 new columns all have safe defaults.
-- ============================================================


-- ===========================================================
-- 1. ALTER public.products
-- ===========================================================
ALTER TABLE public.products
  ADD COLUMN IF NOT EXISTS clinical_use_tags          TEXT[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS avoid_if_tags              TEXT[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS medicine_interaction_flags TEXT[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS counselling_flags          TEXT[] NOT NULL DEFAULT '{}';


-- ===========================================================
-- 2. CREATE INDEX ... products ...
-- ===========================================================
CREATE INDEX IF NOT EXISTS products_clinical_use_tags_idx
  ON public.products USING GIN (clinical_use_tags);
CREATE INDEX IF NOT EXISTS products_avoid_if_tags_idx
  ON public.products USING GIN (avoid_if_tags);
CREATE INDEX IF NOT EXISTS products_reviewed_idx
  ON public.products (reviewed) WHERE reviewed = true;


-- ===========================================================
-- 3. DELETE + INSERT 103 Herbs of Gold products
-- ===========================================================
-- Idempotency guard: the seed has no natural unique key, so wipe any
-- existing HOG rows before re-inserting. Brand='Herbs of Gold' is
-- unique to this seed.
